// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract Bbillionaire is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant MONTH = 30 days;
    uint256 public constant BPS = 10_000;

    IERC20 public immutable jsav;
    uint256 public immutable minInvestment;
    uint256 public immutable maxInvestment;
    uint256 public immutable lifetimeLimit;

    address public immutable rootReferrer;
    address public feeWallet;

    struct User {
        address referrer;
        uint256 directs;
        uint256 totalInvested;
        uint256 bonusCursor;
        uint256 lastClaimAt; // for once-per-month withdraw
        bool exists;
        bool held;
        bool blocked;
    }

    struct Investment {
        uint256 principal;
        uint256 startedAt;
        uint256 roiCredited;
        uint256 earned;     // ROI + level income ever credited including claimed
        uint256 unclaimed;
    }

    mapping(address => User) public users;
    mapping(address => Investment[]) public investments;

    event Invested(address indexed user, uint256 indexed investmentId, uint256 principal, uint256 fee);
    event ROIAccrued(address indexed user, uint256 indexed investmentId, uint256 amount);
    event LevelIncome(address indexed from, address indexed to, uint256 indexed investmentId, uint8 level, uint256 amount);
    event Claimed(address indexed user, uint256 indexed investmentId, uint256 amount);
    event ClaimedAll(address indexed user, uint256 amount, uint256 count);
    event RewardsFunded(address indexed funder, uint256 amount);
    event UserHeld(address indexed user, bool held);
    event UserBlocked(address indexed user, bool blocked);

    constructor(address _feeWallet, address _rootReferrer) Ownable(msg.sender) {
        require(_feeWallet != address(0), "Invalid fee wallet");
        require(_rootReferrer != address(0), "Invalid root");

        address tokenAddress = 0x418B7e6BBc48Ca93126c22A1e83b6420A4E0C6fD;
        require(tokenAddress.code.length != 0, "JSAV not on this chain");

        uint8 decimals = IERC20Metadata(tokenAddress).decimals();
        require(decimals <= 24, "Unsupported decimals");
        uint256 unit = 10 ** uint256(decimals);

        jsav = IERC20(tokenAddress);
        minInvestment = 100 * unit;
        maxInvestment = 500 * unit;
        lifetimeLimit = 100_000 * unit;

        feeWallet = _feeWallet;
        rootReferrer = _rootReferrer;
        users[_rootReferrer].exists = true;
    }

    function investmentCount(address account) external view returns (uint256) {
        return investments[account].length;
    }

    function nextClaimAt(address account) external view returns (uint256) {
        uint256 last = users[account].lastClaimAt;
        if(last == 0) return 0; // can claim immediately if never claimed
        return last + MONTH;
    }

    function invest(uint256 principal, address referrer) external nonReentrant {
        User storage user = users[msg.sender];
        require(!user.held && !user.blocked, "User restricted");
        require(principal >= minInvestment && principal <= maxInvestment, "Investment outside limits");
        require(user.totalInvested + principal <= lifetimeLimit, "Address lifetime limit");

        if (!user.exists) {
            address parent = referrer == address(0) ? rootReferrer : referrer;
            require(parent != msg.sender && users[parent].exists, "Invalid referrer");
            user.exists = true;
            user.referrer = parent;
            users[parent].directs++;
        }

        uint256 fee = principal / 10; // 10% extra
        uint256 cost = principal + fee;
        uint256 beforeBalance = jsav.balanceOf(address(this));
        jsav.safeTransferFrom(msg.sender, address(this), cost);
        require(jsav.balanceOf(address(this)) - beforeBalance == cost, "Nonstandard token transfer");
        jsav.safeTransfer(feeWallet, fee);

        uint256 investmentId = investments[msg.sender].length;
        investments[msg.sender].push(Investment({
            principal: principal,
            startedAt: block.timestamp,
            roiCredited: 0,
            earned: 0,
            unclaimed: 0
        }));
        user.totalInvested += principal;

        emit Invested(msg.sender, investmentId, principal, fee);
    }

    // Booking ROI is permissionless and NOT limited to once per month
    function accrue(address investor, uint256 investmentId) external nonReentrant {
        require(!users[investor].blocked, "Investor blocked");
        _accrue(investor, investmentId);
    }

    // Claim ONE investment - once per 30 days per USER
    function claim(uint256 investmentId) external nonReentrant {
        User storage user = users[msg.sender];
        require(!user.held && !user.blocked, "User restricted");
        require(block.timestamp >= user.lastClaimAt + MONTH, "Withdraw: once per 30 days");

        _accrue(msg.sender, investmentId);

        Investment storage position = investments[msg.sender][investmentId];
        uint256 amount = position.unclaimed;
        require(amount != 0, "Nothing to claim");

        position.unclaimed = 0;
        user.lastClaimAt = block.timestamp;
        jsav.safeTransfer(msg.sender, amount);

        emit Claimed(msg.sender, investmentId, amount);
    }

    // Claim ALL investments at once - also once per 30 days per USER
    // Recommended: use this to avoid needing 5 months to claim 5 investments
    function claimAll() external nonReentrant {
        User storage user = users[msg.sender];
        require(!user.held && !user.blocked, "User restricted");
        require(block.timestamp >= user.lastClaimAt + MONTH, "Withdraw: once per 30 days");
        
        uint256 len = investments[msg.sender].length;
        require(len != 0, "No investment");
        
        uint256 total;
        for(uint256 i = 0; i < len; i++){
            _accrue(msg.sender, i);
            Investment storage position = investments[msg.sender][i];
            if(position.unclaimed != 0){
                total += position.unclaimed;
                position.unclaimed = 0;
            }
        }
        require(total != 0, "Nothing to claim");
        user.lastClaimAt = block.timestamp;
        jsav.safeTransfer(msg.sender, total);
        emit ClaimedAll(msg.sender, total, len);
    }

    function projectedUnclaimed(address account, uint256 investmentId) external view returns (uint256) {
        Investment storage position = investments[account][investmentId];
        return position.unclaimed + _newROI(position);
    }

    function fundRewards(uint256 amount) external nonReentrant {
        require(amount != 0, "Zero amount");
        uint256 beforeBalance = jsav.balanceOf(address(this));
        jsav.safeTransferFrom(msg.sender, address(this), amount);
        require(jsav.balanceOf(address(this)) - beforeBalance == amount, "Nonstandard token transfer");
        emit RewardsFunded(msg.sender, amount);
    }

    function setHeld(address account, bool held) external onlyOwner {
        require(account != address(0), "Invalid account");
        users[account].held = held;
        emit UserHeld(account, held);
    }

    function setBlocked(address account, bool blocked) external onlyOwner {
        require(account != address(0), "Invalid account");
        users[account].blocked = blocked;
        emit UserBlocked(account, blocked);
    }

    function setFeeWallet(address newWallet) external onlyOwner {
        require(newWallet != address(0), "Invalid fee wallet");
        feeWallet = newWallet;
    }

    function _scheduledROI(Investment storage position) private view returns (uint256) {
        // 10% per 30 days continuously
        return (position.principal * (block.timestamp - position.startedAt)) / (10 * MONTH);
    }

    function _newROI(Investment storage position) private view returns (uint256) {
        uint256 remaining = 2 * position.principal - position.earned;
        if (remaining == 0) return 0;
        uint256 scheduled = _scheduledROI(position);
        if (scheduled <= position.roiCredited) return 0;
        uint256 due = scheduled - position.roiCredited;
        return due < remaining ? due : remaining;
    }

    function _accrue(address investor, uint256 investmentId) private {
        Investment storage position = investments[investor][investmentId];
        uint256 roi = _newROI(position);
        if (roi == 0) return;

        position.roiCredited += roi;
        position.earned += roi;
        position.unclaimed += roi;
        emit ROIAccrued(investor, investmentId, roi);

        address upline = users[investor].referrer;
        for (uint8 level = 1; level <= 5 && upline != address(0); level++) {
            User storage recipient = users[upline];
            if (recipient.directs >= level && !recipient.held && !recipient.blocked) {
                uint256 rate = level == 1 ? 500 : level == 2 ? 300 : level == 3 ? 100 : 50;
                _creditLevelIncome(investor, upline, level, (roi * rate) / BPS);
            }
            upline = recipient.referrer;
        }
    }

    function _bonusRoom(Investment storage position) private view returns (uint256) {
        uint256 remaining = 2 * position.principal - position.earned;
        if (remaining == 0) return 0;
        uint256 scheduled = _scheduledROI(position);
        uint256 unbookedROI = scheduled > position.roiCredited ? scheduled - position.roiCredited : 0;
        return remaining > unbookedROI ? remaining - unbookedROI : 0;
    }

    function _creditLevelIncome(address from, address recipient, uint8 level, uint256 amount) private {
        User storage user = users[recipient];
        Investment[] storage positions = investments[recipient];
        uint256 index = user.bonusCursor;
        while (amount != 0 && index < positions.length) {
            Investment storage position = positions[index];
            uint256 room = _bonusRoom(position);
            if (room == 0) { index++; continue; }
            uint256 credit = amount < room ? amount : room;
            position.earned += credit;
            position.unclaimed += credit;
            amount -= credit;
            emit LevelIncome(from, recipient, index, level, credit);
            if (credit == room) index++;
        }
        user.bonusCursor = index;
    }
}

